import * as E from './engine.js';

export function auditDataset(rows,cols=E.columns(rows)) {
 const fields=E.profile(rows,cols),missingRows=rows.flatMap((row,index)=>{const keys=cols.filter(k=>E.missing(row[k]));return keys.length?[{index,keys}]:[];}),complete=rows.length-missingRows.length;
 const seen=new Set(),duplicates=[];rows.forEach((row,index)=>{const key=JSON.stringify(cols.map(k=>row[k]));if(seen.has(key))duplicates.push(index);else seen.add(key);});
 const measures=fields.filter(f=>f.type==='number'&&!/(^id$|_id$|^year$|编号|年份)/i.test(f.key));
 const ranges=measures.map(f=>{const stats=E.describe(rows.map(r=>r[f.key])),iqr=stats.q3-stats.q1,low=stats.q1-1.5*iqr,high=stats.q3+1.5*iqr,indices=rows.flatMap((r,i)=>E.numeric(r[f.key])&&(r[f.key]<low||r[f.key]>high)?[i]:[]);return {key:f.key,...stats,low,high,indices};});
 const outlierMap=new Map();ranges.forEach(f=>f.indices.forEach(index=>{if(!outlierMap.has(index))outlierMap.set(index,[]);outlierMap.get(index).push(f.key);}));
 const constants=fields.filter(f=>f.unique===1),categories=fields.filter(f=>f.type==='text'&&f.unique>0&&f.unique<=30).sort((a,b)=>Number(a.unique===1)-Number(b.unique===1)||a.unique-b.unique);
 const timeFields=fields.filter(f=>f.type==='date'||f.type==='number'&&/(^year$|_year$|年份|年度)/i.test(f.key)&&rows.every(r=>E.missing(r[f.key])||Number.isInteger(r[f.key])&&r[f.key]>=1000&&r[f.key]<=3000));
 return {fields,total:rows.length,complete,missingRows,missingCells:fields.reduce((n,f)=>n+f.missing,0),missingFields:fields.filter(f=>f.missing).sort((a,b)=>b.missing-a.missing),duplicates,constants,ranges,outlierRows:[...outlierMap].map(([index,keys])=>({index,keys})),categories,timeFields};
}
export function categoryOverview(rows,key) {
 const groups=new Map();rows.forEach(row=>{const value=E.missing(row[key])?null:row[key],id=JSON.stringify(value);if(!groups.has(id))groups.set(id,{key:value,count:0});groups.get(id).count++;});
 const all=[...groups.values()].sort((a,b)=>b.count-a.count),shown=all.slice(0,6),missing=all.find(g=>g.key===null);
 if(missing&&!shown.includes(missing))shown[shown.length-1]=missing;
 const selected=new Set(shown),rest=all.filter(g=>!selected.has(g)).reduce((n,g)=>n+g.count,0);
 return {all,shown,rest,total:rows.length};
}
export function timeOverview(rows,field) {
 const groups=new Map(),dates=[];let missing=0;
 rows.forEach(row=>{const v=row[field.key];if(E.missing(v)){missing++;return;}const value=field.type==='number'?String(v):String(v).slice(0,10);dates.push(value);const year=value.slice(0,4);groups.set(year,(groups.get(year)||0)+1);});
 dates.sort();const all=[...groups].sort(([a],[b])=>a.localeCompare(b)).map(([key,count])=>({key,count}));
 return {all,shown:all.slice(0,12),start:dates[0]??null,end:dates.at(-1)??null,valid:dates.length,missing,total:rows.length};
}

export function createDataOverview({t,esc,label,val,fmt,color,select,btn}) {
 const typeName=type=>type==='number'?t('数值','Numeric'):type==='date'?t('日期','Date'):t('文本','Text');
 const bars=(list,max)=>list.map((g,i)=>`<div class="overview-bar-row"><span title="${esc(g.name)}">${esc(g.name)}</span><div><i style="width:${max?g.count/max*100:0}%;background:${g.color||color[i%color.length]}"></i></div><b>${fmt(g.count)}</b></div>`).join('');
 function composition(rows,a,state,sample){
  const available=a.categories,key=available.some(f=>f.key===state.group)?state.group:sample&&available.some(f=>f.key==='species')?'species':available[0]?.key||'';state.group=key;
  if(!key)return `<section class="card overview-card"><div class="overview-card-head"><h2>${t('字段组成','Field composition')}</h2></div><div class="overview-types">${['number','text','date'].map((type,i)=>`<div><span style="background:${color[i]}">${type==='number'?'#':type==='date'?'◷':'Aa'}</span><b>${a.fields.filter(f=>f.type===type).length}</b><p>${typeName(type)}${t('字段',' fields')}</p></div>`).join('')}</div><p class="overview-note">${t('根据全部有效值识别字段类型。全空字段归为文本。','Types use all present values. Entirely empty fields are classified as text.')}</p></section>`;
  const g=categoryOverview(rows,key),items=[...g.shown,...(g.rest?[{key:null,count:g.rest,isOther:true}]:[])],total=g.total||1;let offset=0;
  const ring=items.map((d,i)=>{const fraction=d.count/total,length=fraction*376.99,c=i===6?'#bcc1d4':color[i%color.length],part=`<circle cx="84" cy="84" r="60" fill="none" stroke="${c}" stroke-width="22" stroke-dasharray="${length} ${376.99-length}" stroke-dashoffset="${-offset}"><title>${esc(d.isOther?t('其余类别','Other categories'):val(d.key))}: ${d.count} (${fmt(fraction*100,1)}%)</title></circle>`;offset+=length;return part;}).join('');
  return `<section class="card overview-card"><div class="overview-card-head"><h2>${t('样本构成','Sample composition')}</h2><label class="overview-select"><span>${t('分类字段','Category')}</span>${select('overviewGroup',available.map(f=>[f.key,label(f.key)]),key)}</label></div><div class="overview-composition"><div class="overview-ring"><svg viewBox="0 0 168 168" role="img" aria-label="${esc(label(key))} ${t('样本构成','sample composition')}"><circle cx="84" cy="84" r="60" fill="none" stroke="#eeedf5" stroke-width="22"/>${ring}</svg><div><strong>${fmt(g.total)}</strong><span>${t('条记录','records')}</span></div></div><div class="overview-category-list">${items.map((d,i)=>`<div><span><i style="background:${i===6?'#bcc1d4':color[i%color.length]}"></i>${esc(d.isOther?t('其余类别','Other categories'):val(d.key))}</span><b>${fmt(d.count)}<small>${fmt(d.count/total*100,1)}%</small></b></div>`).join('')}</div></div><p class="overview-note">${t(`${g.all.length} 个类别，缺失值单列，合计覆盖全部记录。`,`${g.all.length} categories, including an explicit missing category. Counts cover all records.`)}</p></section>`;
 }
 function coverage(rows,a,state){
  const available=a.timeFields,key=available.some(f=>f.key===state.time)?state.time:available[0]?.key||'';state.time=key;
  if(!key){const unique=a.fields.filter(f=>f.unique===a.total&&a.total>1&&f.missing===0);return `<section class="card overview-card"><div class="overview-card-head"><h2>${t('字段取值特征','Field value structure')}</h2></div><div class="overview-structure-summary"><div><b>${a.fields.length}</b><span>${t('个字段','fields')}</span></div><div><b>${unique.length}</b><span>${t('列取值不重复','all-unique fields')}</span></div><div><b>${a.constants.length}</b><span>${t('列只有一种值','constant fields')}</span></div></div>${bars(['number','text','date'].map((type,i)=>({name:typeName(type)+t('字段',' fields'),count:a.fields.filter(f=>f.type===type).length,color:color[i]})),a.fields.length)}<p class="overview-note">${t('唯一值字段可作为标识候选；常量字段在当前数据中没有区分度。','All-unique fields may be identifiers. Constant fields do not distinguish these records.')}</p></section>`;}
  const f=available.find(f=>f.key===key),g=timeOverview(rows,f),peak=Math.max(1,...g.shown.map(v=>v.count));
  const timeline=`<svg class="overview-timeline" viewBox="0 0 520 170" role="img" aria-label="${esc(label(key))} ${t('年度记录数','annual record counts')}"><line x1="25" x2="505" y1="137" y2="137" stroke="#e2e2ef"/>${g.shown.map((d,i)=>{const step=470/g.shown.length,x=30+step*(i+.5),height=d.count/peak*95;return `<rect x="${x-Math.min(28,step*.3)}" y="${137-height}" width="${Math.min(56,step*.6)}" height="${height}" rx="5" fill="${color[i%color.length]}"><title>${d.key}: ${d.count}</title></rect><text x="${x}" y="${128-height}" text-anchor="middle">${fmt(d.count)}</text><text x="${x}" y="160" text-anchor="middle">${d.key}</text>`;}).join('')}</svg>`;
  return `<section class="card overview-card"><div class="overview-card-head"><h2>${t('观测时间覆盖','Observation period')}</h2>${available.length>1?`<label class="overview-select"><span>${t('时间字段','Time field')}</span>${select('overviewTime',available.map(f=>[f.key,label(f.key)]),key)}</label>`:`<span class="overview-field-label">${esc(label(key))}</span>`}</div><div class="overview-time-range"><strong>${esc(g.start??'—')}</strong><span>—</span><strong>${esc(g.end??'—')}</strong><small>${g.all.length} ${t('个观测年份','observation years')}</small></div>${timeline}<p class="overview-note">${t(`年度记录数；${g.valid} 条有时间，${g.missing} 条缺失。${g.all.length>12?'图中展示最早 12 年。':''}`,`Annual counts; ${g.valid} dated records, ${g.missing} missing. ${g.all.length>12?'The earliest 12 years are shown.':''}`)}</p></section>`;
 }
 function health(a){
  const completeness=a.total?a.complete/a.total*100:0,list=a.missingFields.slice(0,6),max=Math.max(1,...list.map(f=>f.missing));
  return `<section class="card data-health"><div class="overview-card-head"><h2>${t('数据完整度与质量检查','Completeness and quality checks')}</h2><span class="overview-field-label">${t('当前工作数据','Working dataset')}</span></div><div class="data-health-grid"><div class="data-completeness"><div class="data-completeness-value"><strong>${fmt(completeness,1)}<span>%</span></strong><div><b>${t('完整记录占比','Complete records')}</b><p>${t('全部字段都有值','Every field has a value')}</p></div></div><div class="health-track" role="img" aria-label="${t('完整记录','Complete')} ${a.complete}; ${t('含缺失记录','Incomplete')} ${a.missingRows.length}"><span style="width:${completeness}%"></span><i style="width:${a.total?100-completeness:0}%"></i></div><div class="health-legend"><span><i></i>${t('完整','Complete')} <b>${fmt(a.complete)}</b></span><span><i class="incomplete"></i>${t('含缺失','Incomplete')} <b>${fmt(a.missingRows.length)}</b></span></div>${a.missingRows.length?btn('inspectQuality',t('查看缺失记录','Inspect missing records'),'rows','small ghost','data-kind="missing"'):''}</div><div class="data-missing-ranking"><div class="spread"><h3>${t('字段缺失数量','Missing cells by field')}</h3><span>${fmt(a.missingCells)} ${t('个空单元格','empty cells')}</span></div>${list.length?list.map(f=>`<button class="missing-rank-row" data-act="qualityField" data-key="${esc(f.key)}"><span>${esc(label(f.key))}</span><i><b style="width:${f.missing/max*100}%"></b></i><strong>${fmt(f.missing)}</strong><small>${fmt(f.missing/Math.max(1,a.total)*100,1)}%</small></button>`).join(''):`<div class="data-quality-clear">✓ ${t('所有字段均无缺失','Every field is complete')}</div>`}${a.missingFields.length>6?`<p class="overview-note">${t(`展示缺失最多的 6 / ${a.missingFields.length} 个字段。`,`Showing 6 / ${a.missingFields.length} fields with the most missing cells.`)}</p>`:''}</div></div><div class="data-checks">${[[t('重复记录','Duplicate rows'),a.duplicates.length,'duplicates',t('全部字段完全相同的多余记录','Extra rows identical across all fields')],[t('疑似异常记录','Potential outlier rows'),a.outlierRows.length,'outliers',t('任一数值超出该字段 1.5×IQR 范围','Any metric outside its 1.5×IQR fences')],[t('常量字段','Constant fields'),a.constants.length,'constants',t('非空值只有一种取值的字段','Fields with one distinct present value')]].map(([title,n,kind,desc])=>`<button class="data-check ${n?'has-findings':''}" data-act="inspectQuality" data-kind="${kind}"><span class="data-check-icon">${n?'!':'✓'}</span><div><b>${title}</b><small>${desc}</small></div><strong>${fmt(n)}</strong><span>›</span></button>`).join('')}</div></section>`;
 }
 return {render(rows,cols,state,sample){const a=auditDataset(rows,cols);return `<div class="data-overview-grid">${composition(rows,a,state,sample)}${coverage(rows,a,state)}</div>${health(a)}`;}};
}
